// === Tab: mySketch ===
// Made for #WCCChallenge
// If you haven't tried it yet, zoom into a line until it fills your whole screen.

let mindim;
let lines = [];
inverseMode = false;

function setup() {
	mindim = max(windowWidth, windowHeight);
	createCanvas(mindim, mindim);
	background(100);
}

function distToLine(x,y,x1,y1,x2,y2){
	let ldx = x2-x1;
	let ldy = y2-y1;
	let magSq = ldx*ldx + ldy*ldy;
	return abs((x-x1)*ldy - (y-y1)*ldx)/sqrt(magSq);
}

function addRandomLine(){
	let cx = random()*2-1;
	let cy = random()*2-1;
	let theta = random()*TAU;
	let dist = random()*0.2+0.1;
	lines.push([cx+dist*cos(theta),cy+dist*sin(theta),cx-dist*cos(theta),cy-dist*sin(theta),0.00006]);
}

function update(){
	newLines = [];
	let ox = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/mindim*2-1;
	let oy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/mindim*2-1;
	for(let l of lines){
		l[0] = (l[0]-ox)*1.02+ox;
		l[1] = (l[1]-oy)*1.02+oy;
		l[2] = (l[2]-ox)*1.02+ox;
		l[3] = (l[3]-oy)*1.02+oy;
		l[4] = l[4]*1.02;
		if(l[4]>12)
		l[4] = l[4]*(1-l[4]*0.0001);
		if((l[0]<-1-l[4] && l[2]<-1-l[4]) || (l[1]<-1-l[4] && l[3]<-1-l[4]) || (l[0]>1+l[4] && l[2]>1+l[4]) || (l[1]>1+l[4] && l[3]>1+l[4]))continue;
		if(distToLine(0,0,l[0],l[1],l[2],l[3])>1.414+l[4]/2)continue;
		newLines.push(l);
		if(distToLine(0,0,l[0],l[1],l[2],l[3])<l[4]/2-1.5){
			inverseMode = !inverseMode;
			newLines = [];
			break;
		}
	}
	lines = newLines;
	for(let i=0; i<50; i++)
	addRandomLine();
}

function draw() {
		background(244);
	if(!inverseMode){
		stroke(22);
	}else{
		noStroke();
		fill(22);
		rect(0,0,mindim,mindim);
		stroke(244);
	}
	noFill();
	for(let l of lines){
		strokeWeight(l[4]*mindim/2);
		line(mindim/2*(1+l[0]),mindim/2*(1+l[1]),mindim/2*(1+l[2]),mindim/2*(1+l[3]));
	}
	update();
}
